			if (entry.isDirectory() && SKIPPED_DIRS.has(entry.name)) continue;
			const path = `${rel}${entry.name}${entry.isDirectory() ? "/" : ""}`;
			out.push(path);
			if (entry.isDirectory() && depth < MAX_SCAN_DEPTH) walk(join(dir, entry.name), `${path}`, depth + 1);
